<script setup lang="ts">
import {ref,onUnmounted} from 'vue';
import {useI18n} from 'vue-i18n';
import {useDashboard} from '../stores/dashboard';
import {configureNativeApi,isNative} from '../api/transport';
const {t,te}=useI18n();const store=useDashboard();const mode=ref<'login'|'register'>('register');
const email=ref('');const password=ref('');const confirmation=ref('');const name=ref('');const market=ref('TH');const apiUrl=ref('');const legacyToken=ref('');const busy=ref(false);const error=ref('');
onUnmounted(()=>{password.value='';confirmation.value='';legacyToken.value='';});
function configure(){if(isNative)configureNativeApi(apiUrl.value);}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{configure();await store.authenticate(mode.value,{email:email.value,password:password.value,...(mode.value==='register'?{name:name.value,password_confirmation:confirmation.value,market:market.value}:{})});}catch(e){error.value=e instanceof Error&&te(e.message)?e.message:'authFailed';}finally{password.value='';confirmation.value='';busy.value=false;}}
async function connectToken(){if(busy.value)return;busy.value=true;error.value='';try{configure();store.logout();store.token=legacyToken.value.trim();legacyToken.value='';await store.refresh();}catch(e){error.value=e instanceof Error&&te(e.message)?e.message:'authFailed';}finally{busy.value=false;}}
</script>
<template><section class="widget connect account-form"><span class="eyebrow">KINDEE · YOUR EVERYDAY COMPANION</span><h2>{{t('authTitle')}}</h2><p>{{t('authIntro')}}</p><div class="account-modes" role="group" :aria-label="t('authTitle')"><button v-for="item in (['register','login'] as const)" :key="item" :aria-pressed="mode===item" :class="{active:mode===item}" @click="mode=item;password='';confirmation=''">{{t(item==='login'?'authLogin':'authRegister')}}</button></div><form @submit.prevent="submit"><label v-if="isNative">{{t('apiUrl')}}<input v-model="apiUrl" type="url" placeholder="http://192.168.1.10:8080" required><small>{{t('apiUrlHelp')}}</small></label><label v-if="mode==='register'">{{t('authName')}}<input v-model="name" autocomplete="name" required maxlength="80"></label><label>{{t('authEmail')}}<input v-model="email" type="email" autocomplete="username" required maxlength="254" autocapitalize="none" spellcheck="false"></label><label>{{t('authPassword')}}<input v-model="password" type="password" :autocomplete="mode==='register'?'new-password':'current-password'" :minlength="mode==='register'?12:1" maxlength="128" required><small v-if="mode==='register'">{{t('authPasswordHelp')}}</small></label><label v-if="mode==='register'">{{t('authConfirm')}}<input v-model="confirmation" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><label v-if="mode==='register'">{{t('market')}}<select v-model="market"><option value="TH">Thailand · THB</option><option value="US">USA · USD</option></select></label><button :disabled="busy||store.loading">{{t(busy?'loading':mode==='register'?'authRegister':'authLogin')}}</button></form><p v-if="error" class="error" role="alert">{{t(error)}}</p><p class="widget-note">{{t('authMemory')}}</p><details><summary>{{t('authAdvanced')}}</summary><form @submit.prevent="connectToken"><label>{{t('token')}}<input v-model="legacyToken" type="password" required minlength="64" maxlength="64" autocomplete="off"></label><button :disabled="busy">{{t('connect')}}</button></form></details><RouterLink class="inline-link" to="/recipes">{{t('openRecipes')}} →</RouterLink></section></template>
